// Provider handle interning. IDs are generated by the owning binding registry,
// not URL strings, rule-list positions or independent arena NodeIds.
struct NativeImportHandle {
    identity: u64,
    publication: Rc<RetainedStylesheetRecord>,
    occurrence: oryn_layout::cssom::native_import_graph::OccurrenceId,
    registry: Rc<RefCell<NativeCssHandleRegistry>>,
    _charge: std::sync::Arc<dyn Send + Sync>,
}
struct NativeSheetHandle {
    identity: u64,
    publication: Rc<RetainedStylesheetRecord>,
    sheet: oryn_layout::cssom::native_import_graph::NativeSheet,
    registry: Rc<RefCell<NativeCssHandleRegistry>>,
    _charge: std::sync::Arc<dyn Send + Sync>,
}
struct NativeRuleHandle {
    identity: u64,
    publication: Rc<RetainedStylesheetRecord>,
    rule: oryn_layout::cssom::native_import_graph::NativeRule,
    registry: Rc<RefCell<NativeCssHandleRegistry>>,
    _charge: std::sync::Arc<dyn Send + Sync>,
}
#[derive(Default)]
struct NativeCssHandleRegistry {
    next: u64,
    sheets: Vec<Weak<NativeSheetHandle>>,
    imports: Vec<Weak<NativeImportHandle>>,
    rules: Vec<Weak<NativeRuleHandle>>,
}
impl NativeCssHandleRegistry {
    fn rule(
        registry: &Rc<RefCell<Self>>,
        publication: Rc<RetainedStylesheetRecord>,
        rule: oryn_layout::cssom::native_import_graph::NativeRule,
    ) -> Result<Rc<NativeRuleHandle>, String> {
        // Admission can reenter; no registry borrow exists yet. Charge is
        // declared before state so all error/return drops release state first.
        let charge = publication.admission.reserve(
            std::mem::size_of::<NativeRuleHandle>()
                + 2 * std::mem::size_of::<usize>()
                + std::mem::size_of::<Weak<NativeRuleHandle>>(),
        )?;
        let mut state = registry
            .try_borrow_mut()
            .map_err(|_| "native CSS identity borrow conflict")?;
        state.rules.retain(|old| old.strong_count() != 0);
        if let Some(existing) = state.rules.iter().filter_map(Weak::upgrade).find(|handle| {
            Rc::ptr_eq(&handle.publication, &publication) && handle.rule.same_rule(&rule)
        }) {
            return Ok(existing);
        }

        state
            .rules
            .try_reserve(1)
            .map_err(|_| "native CSS rule metadata allocation")?;
        let identity = state.next_identity()?;
        let handle = Rc::new(NativeRuleHandle {
            identity,
            publication,
            rule,
            registry: registry.clone(),
            _charge: charge,
        });
        state.rules.push(Rc::downgrade(&handle));
        drop(state);
        Ok(handle)
    }
    fn next_identity(&mut self) -> Result<u64, String> {
        let id = self
            .next
            .checked_add(1)
            .ok_or("native CSS identity exhausted")?;
        self.next = id;
        Ok(id)
    }
    fn sheet(
        registry: &Rc<RefCell<Self>>,
        publication: Rc<RetainedStylesheetRecord>,
        sheet: oryn_layout::cssom::native_import_graph::NativeSheet,
    ) -> Result<Rc<NativeSheetHandle>, String> {
        // Admission can reenter; no registry borrow exists yet. Charge is
        // declared before state so all error/return drops release state first.
        let charge = publication.admission.reserve(
            std::mem::size_of::<NativeSheetHandle>()
                + 2 * std::mem::size_of::<usize>()
                + std::mem::size_of::<Weak<NativeSheetHandle>>(),
        )?;
        let mut state = registry
            .try_borrow_mut()
            .map_err(|_| "native CSS identity borrow conflict")?;
        state.sheets.retain(|old| old.strong_count() != 0);
        if let Some(existing) = state
            .sheets
            .iter()
            .filter_map(Weak::upgrade)
            .find(|handle| {
                Rc::ptr_eq(&handle.publication, &publication) && handle.sheet.same_sheet(&sheet)
            })
        {
            return Ok(existing);
        }

        state
            .sheets
            .try_reserve(1)
            .map_err(|_| "native CSS handle metadata allocation")?;
        let identity = state.next_identity()?;
        let handle = Rc::new(NativeSheetHandle {
            identity,
            publication,
            sheet,
            registry: registry.clone(),
            _charge: charge,
        });
        state.sheets.push(Rc::downgrade(&handle));
        drop(state);
        Ok(handle)
    }
    fn import(
        registry: &Rc<RefCell<Self>>,
        publication: Rc<RetainedStylesheetRecord>,
        occurrence: oryn_layout::cssom::native_import_graph::OccurrenceId,
    ) -> Result<Rc<NativeImportHandle>, String> {
        // Admission can reenter; no registry borrow exists yet. Charge is
        // declared before state so all error/return drops release state first.
        let charge = publication.admission.reserve(
            std::mem::size_of::<NativeImportHandle>()
                + 2 * std::mem::size_of::<usize>()
                + std::mem::size_of::<Weak<NativeImportHandle>>(),
        )?;
        let mut state = registry
            .try_borrow_mut()
            .map_err(|_| "native CSS identity borrow conflict")?;
        state.imports.retain(|old| old.strong_count() != 0);
        if let Some(existing) = state
            .imports
            .iter()
            .filter_map(Weak::upgrade)
            .find(|handle| {
                Rc::ptr_eq(&handle.publication, &publication) && handle.occurrence == occurrence
            })
        {
            return Ok(existing);
        }

        state
            .imports
            .try_reserve(1)
            .map_err(|_| "native CSS import metadata allocation")?;
        let identity = state.next_identity()?;
        let handle = Rc::new(NativeImportHandle {
            identity,
            publication,
            occurrence,
            registry: registry.clone(),
            _charge: charge,
        });
        state.imports.push(Rc::downgrade(&handle));
        drop(state);
        Ok(handle)
    }
}
impl NativeImportHandle {
    fn require_origin_clean(&self) -> Result<(), oryn_js::v8_bindings::BindingNativeCssError> {
        let occurrence = self.snapshot()?;
        if self.publication.responses.try_borrow().map_err(|_| oryn_js::v8_bindings::BindingNativeCssError::Native("origin proof borrow conflict".into()))?.entries.iter()
            .find(|response| {
                response
                    .sheet
                    .as_ref()
                    .is_some_and(|sheet| sheet.same_sheet(&occurrence.parent))
            })
            .is_some_and(|response| response.proof.origin_clean())
        {
            Ok(())
        } else {
            Err(oryn_js::v8_bindings::BindingNativeCssError::Security)
        }
    }
    fn snapshot(&self) -> Result<oryn_layout::cssom::native_import_graph::NativeImport, String> {
        self.publication
            .graph
            .try_borrow()
            .map_err(|_| "native import read borrow conflict")?
            .occurrence(self.occurrence)
            .ok_or_else(|| "native import occurrence missing".into())
    }
    fn sheet(&self) -> Result<Option<Rc<NativeSheetHandle>>, String> {
        let child = self
            .publication
            .graph
            .try_borrow()
            .map_err(|_| "native import read borrow conflict")?
            .occurrence(self.occurrence)
            .and_then(|entry| entry.child.clone());
        let Some(child) = child else { return Ok(None) };
        NativeCssHandleRegistry::sheet(&self.registry, self.publication.clone(), child).map(Some)
    }
}
impl oryn_js::v8_bindings::BindingNativeImport for NativeImportHandle {
    fn view(
        &self,
    ) -> Result<oryn_js::v8_bindings::BindingRuleView, oryn_js::v8_bindings::BindingNativeCssError> {
        self.require_origin_clean()?;
        self.snapshot()?.view().map(binding_rule_view).map_err(Into::into)
    }
    fn media_count(&self) -> Result<usize, oryn_js::v8_bindings::BindingNativeCssError> {
        self.require_origin_clean()?;
        Ok(self.snapshot()?.media_count())
    }
    fn media_at(
        &self,
        index: usize,
    ) -> Result<Option<String>, oryn_js::v8_bindings::BindingNativeCssError> {
        self.require_origin_clean()?;
        Ok(self.snapshot()?.media_at(index))
    }
    fn identity(&self) -> u64 {
        self.identity
    }
    fn href(&self) -> Result<String, oryn_js::v8_bindings::BindingNativeCssError> {
        self.require_origin_clean()?;
        Ok(self.snapshot()?.href().unwrap_or_default())
    }
    fn layer_name(&self) -> Result<Option<String>, oryn_js::v8_bindings::BindingNativeCssError> {
        self.require_origin_clean()?;
        Ok(self.snapshot()?.layer_name())
    }
    fn supports_text(&self) -> Result<Option<String>, oryn_js::v8_bindings::BindingNativeCssError> {
        self.require_origin_clean()?;
        Ok(self.snapshot()?.supports_text())
    }
    fn media_text(&self) -> Result<String, oryn_js::v8_bindings::BindingNativeCssError> {
        self.require_origin_clean()?;
        Ok(self.snapshot()?.media_text())
    }
    fn media_queries(&self) -> Result<Vec<String>, oryn_js::v8_bindings::BindingNativeCssError> {
        self.require_origin_clean()?;
        Ok(self.snapshot()?.media_queries())
    }
    fn edit_media(
        &self,
        edit: oryn_js::v8_bindings::BindingMediaListEdit<'_>,
    ) -> Result<
        oryn_js::v8_bindings::BindingStylesheetMediaMutation,
        oryn_js::v8_bindings::BindingNativeCssError,
    > {
        use oryn_js::v8_bindings::BindingMediaListEdit as Binding;
        self.require_origin_clean()?;
        use oryn_layout::cssom::MediaListEdit as Native;
        let edit = match edit {
            Binding::Replace(text) => Native::Replace(text),
            Binding::Append(text) => Native::Append(text),
            Binding::Delete(text) => Native::Delete(text),
        };
        let import = self.snapshot()?;
        let revision = self
            .publication
            .mutation_revision
            .get()
            .checked_add(1)
            .ok_or("stylesheet mutation revision exhausted")?;
        let result = self
            .publication
            .graph
            .try_borrow_mut()
            .map_err(|_| "native import media mutation borrow conflict")?
            .edit_import_media(&import, edit, self.publication.admission.as_ref())?;
        if result.changed {
            self.publication.mutation_revision.set(revision)
        }
        Ok(oryn_js::v8_bindings::BindingStylesheetMediaMutation {
            queries: result.queries,
            changed: result.changed,
            not_found: result.not_found,
        })
    }
    fn sheet(
        &self,
    ) -> Result<
        Option<Rc<dyn oryn_js::v8_bindings::BindingNativeStylesheet>>,
        oryn_js::v8_bindings::BindingNativeCssError,
    > {
        NativeImportHandle::sheet(self)
            .map(|sheet| {
                sheet.map(|sheet| sheet as Rc<dyn oryn_js::v8_bindings::BindingNativeStylesheet>)
            })
            .map_err(Into::into)
    }
    fn parent(
        &self,
    ) -> Result<
        Option<Rc<dyn oryn_js::v8_bindings::BindingNativeStylesheet>>,
        oryn_js::v8_bindings::BindingNativeCssError,
    > {
        let graph = self
            .publication
            .graph
            .try_borrow()
            .map_err(|_| "native import parent borrow conflict")?;
        let occurrence = graph
            .occurrence(self.occurrence)
            .ok_or("native import occurrence missing")?;
        let attached = !matches!(
            occurrence.state,
            oryn_layout::cssom::native_import_graph::ImportState::Detached
        );
        drop(graph);
        if !attached {
            return Ok(None);
        }
        NativeCssHandleRegistry::sheet(&self.registry, self.publication.clone(), occurrence.parent)
            .map(|sheet| Some(sheet as Rc<dyn oryn_js::v8_bindings::BindingNativeStylesheet>))
            .map_err(Into::into)
    }
}
impl NativeSheetHandle {
    fn parent(
        &self,
    ) -> Result<Option<Rc<NativeSheetHandle>>, oryn_js::v8_bindings::BindingNativeCssError> {
        let parent = self
            .publication
            .graph
            .try_borrow()
            .map_err(|_| "native stylesheet read borrow conflict")?
            .owner(&self.sheet)
            .map(|entry| entry.parent.clone());
        let Some(parent) = parent else {
            return Ok(None);
        };
        NativeCssHandleRegistry::sheet(&self.registry, self.publication.clone(), parent)
            .map(Some)
            .map_err(Into::into)
    }
}
impl oryn_js::v8_bindings::BindingNativeStylesheet for NativeSheetHandle {
    fn owner_import(&self) -> Result<Option<Rc<dyn oryn_js::v8_bindings::BindingNativeImport>>, oryn_js::v8_bindings::BindingNativeCssError> {
        let occurrence = self.publication.graph.try_borrow()
            .map_err(|_| "native owner rule graph borrow conflict")?
            .owner(&self.sheet).map(|entry| entry.id);
        let Some(occurrence) = occurrence else { return Ok(None); };
        NativeCssHandleRegistry::import(&self.registry, self.publication.clone(), occurrence)
            .map(|handle| Some(handle as Rc<dyn oryn_js::v8_bindings::BindingNativeImport>))
            .map_err(Into::into)
    }

    // title uses the original owner, never a URL-derived surrogate.
    // Add to NativeSheetHandle's implementation; imported sheets have no owning
    // element and therefore no title. The original owner is never inferred by URL.
    fn title(&self) -> Result<Option<String>, oryn_js::v8_bindings::BindingNativeCssError> {
        use oryn_js::v8_bindings::BindingNativeCssError as Error;
        let Some(owner) = self.owner_node()? else {
            return Ok(None);
        };
        let Some(arena) = self.publication.owner.arena.upgrade() else {
            return Ok(None);
        };
        let dom = arena
            .try_borrow()
            .map_err(|_| Error::Native("native CSS title arena borrow conflict".into()))?;
        let record = dom
            .arena()
            .get(owner)
            .map_err(|error| Error::Native(error.to_string()))?;
        // This is a null-namespace HTML content attribute, not the first qualified
        // attribute with the same spelling in another namespace.
        Ok(Some(
            record
                .attributes
                .get_null("title")
                .cloned()
                .unwrap_or_default(),
        ))
    }

    fn disabled(&self) -> Result<bool, oryn_js::v8_bindings::BindingNativeCssError> {
        self.publication.reconcile_owner_state_admitted()
            .map_err(|error| oryn_js::v8_bindings::BindingNativeCssError::Native(error.to_string()))?;
        Ok(self.sheet.disabled())
    }
    fn set_disabled(
        &self,
        disabled: bool,
    ) -> Result<bool, oryn_js::v8_bindings::BindingNativeCssError> {
        self.commit_root_sheet_disabled(disabled)
    }

    fn media_text(&self) -> Result<String, oryn_js::v8_bindings::BindingNativeCssError> {
        self.publication.reconcile_owner_state_admitted()
            .map_err(|error| oryn_js::v8_bindings::BindingNativeCssError::Native(error.to_string()))?;
        Ok(self.sheet.media_text())
    }
    fn media_count(&self) -> Result<usize, oryn_js::v8_bindings::BindingNativeCssError> {
        self.publication.reconcile_owner_state_admitted()
            .map_err(|error| oryn_js::v8_bindings::BindingNativeCssError::Native(error.to_string()))?;
        Ok(self.sheet.media_count())
    }
    fn media_at(
        &self,
        index: usize,
    ) -> Result<Option<String>, oryn_js::v8_bindings::BindingNativeCssError> {
        self.publication.reconcile_owner_state_admitted()
            .map_err(|error| oryn_js::v8_bindings::BindingNativeCssError::Native(error.to_string()))?;
        Ok(self.sheet.media_at(index))
    }
    fn edit_media(
        &self,
        edit: oryn_js::v8_bindings::BindingMediaListEdit<'_>,
    ) -> Result<
        oryn_js::v8_bindings::BindingStylesheetMediaMutation,
        oryn_js::v8_bindings::BindingNativeCssError,
    > {
        use oryn_js::v8_bindings::BindingMediaListEdit as Binding;
        use oryn_layout::cssom::MediaListEdit as Native;
        let edit = match edit {
            Binding::Replace(text) => Native::Replace(text),
            Binding::Append(text) => Native::Append(text),
            Binding::Delete(text) => Native::Delete(text),
        };
        let result = self.commit_root_sheet_media(edit)?;
        Ok(oryn_js::v8_bindings::BindingStylesheetMediaMutation {
            queries: result.queries,
            changed: result.changed,
            not_found: result.not_found,
        })
    }

    fn owner_node(&self) -> Result<Option<NodeId>, oryn_js::v8_bindings::BindingNativeCssError> {
        let identity = self.publication.owner.document;
        if !self.publication.owner.lifecycle.current(
            oryn_js::v8_bindings::BindingStylesheetDocumentOwner {
                realm: identity.realm,
                document: identity.document,
                document_generation: identity.document_generation,
                stream_epoch: identity.stream_epoch,
            },
        ) {
            return Ok(None);
        }
        let graph = self
            .publication
            .graph
            .try_borrow()
            .map_err(|_| "native CSS owner graph borrow conflict")?;
        // An imported child sheet never has an owner DOM element, even when its
        // import rule remains attached. Only the exact root sheet can own one.
        if !graph.root().same_sheet(&self.sheet) {
            return Ok(None);
        }
        drop(graph);
        let Some(arena) = self.publication.owner.arena.upgrade() else {
            return Ok(None);
        };
        let dom = arena
            .try_borrow()
            .map_err(|_| "native CSS owner arena borrow conflict")?;
        let owner = self.publication.owner.node;
        // A retained root remains readable after detachment, but loses ownerNode.
        let Ok(record) = dom.arena().get(owner) else {
            return Ok(None);
        };
        if record.owner_document != Some(self.publication.owner.document.document)
            || !dom.is_connected(owner).map_err(|error| error.to_string())?
            || dom
                .arena()
                .stylesheet_revision(owner)
                .map_err(|error| error.to_string())?
                != self.publication.owner.revision
        {
            return Ok(None);
        }
        Ok(Some(owner))
    }

    fn identity(&self) -> u64 {
        self.identity
    }
    fn rule_at(
        &self,
        index: usize,
    ) -> Result<
        Option<Rc<dyn oryn_js::v8_bindings::BindingNativeRule>>,
        oryn_js::v8_bindings::BindingNativeCssError,
    > {
        if !self.origin_clean() {
            return Err(oryn_js::v8_bindings::BindingNativeCssError::Security);
        }
        let graph = self
            .publication
            .graph
            .try_borrow()
            .map_err(|_| "native CSS rule lookup borrow conflict")?;
        let rule = match graph.rule_at(&self.sheet, &[], index, self.publication.admission.as_ref())
        {
            Ok(rule) => rule,
            Err(oryn_layout::cssom::RuleMutationError::IndexSize) => return Ok(None),
            Err(error) => return Err(format!("{error:?}").into()),
        };
        drop(graph);
        NativeCssHandleRegistry::rule(&self.registry, self.publication.clone(), rule)
            .map(|handle| Some(handle as Rc<dyn oryn_js::v8_bindings::BindingNativeRule>))
            .map_err(Into::into)
    }
    fn import_at(
        &self,
        index: usize,
    ) -> Result<
        Option<Rc<dyn oryn_js::v8_bindings::BindingNativeImport>>,
        oryn_js::v8_bindings::BindingNativeCssError,
    > {
        if !self.origin_clean() {
            return Err(oryn_js::v8_bindings::BindingNativeCssError::Security);
        }
        let occurrence = self
            .publication
            .graph
            .try_borrow()
            .map_err(|_| "native sheet occurrence borrow conflict")?
            .imports()
            .find(|entry| entry.parent.same_sheet(&self.sheet) && entry.index == index)
            .map(|entry| entry.id);
        let Some(occurrence) = occurrence else {
            return Ok(None);
        };
        NativeCssHandleRegistry::import(&self.registry, self.publication.clone(), occurrence)
            .map(|handle| Some(handle as Rc<dyn oryn_js::v8_bindings::BindingNativeImport>))
            .map_err(Into::into)
    }
    fn rule_count(&self) -> Result<usize, oryn_js::v8_bindings::BindingNativeCssError> {
        if !self.origin_clean() {
            return Err(oryn_js::v8_bindings::BindingNativeCssError::Security);
        }
        self.publication
            .graph
            .try_borrow()
            .map_err(|_| "native sheet read borrow conflict")?
            .rule_count(&self.sheet)
            .map_err(|error| {
                oryn_js::v8_bindings::BindingNativeCssError::Native(format!("{error:?}"))
            })
    }
    fn rules(
        &self,
    ) -> Result<
        Vec<oryn_js::v8_bindings::BindingRuleView>,
        oryn_js::v8_bindings::BindingNativeCssError,
    > {
        if !self.origin_clean() {
            return Err(oryn_js::v8_bindings::BindingNativeCssError::Security);
        }
        self.publication
            .graph
            .try_borrow()
            .map_err(|_| "native sheet read borrow conflict")?
            .views(&self.sheet)
            .map(|rules| rules.into_iter().map(binding_rule_view).collect())
            .map_err(Into::into)
    }
    fn href(&self) -> Option<String> {
        Some(self.sheet.base_url())
    }
    fn origin_clean(&self) -> bool {
        let Ok(responses) = self.publication.responses.try_borrow() else { return false; };
        responses.entries.iter()
            .find(|response| {
                response
                    .sheet
                    .as_ref()
                    .is_some_and(|sheet| sheet.same_sheet(&self.sheet))
            })
            .map(|response| response.proof.origin_clean())
            .unwrap_or(false)
    }
    fn parent(
        &self,
    ) -> Result<
        Option<Rc<dyn oryn_js::v8_bindings::BindingNativeStylesheet>>,
        oryn_js::v8_bindings::BindingNativeCssError,
    > {
        NativeSheetHandle::parent(self)
            .map(|sheet| {
                sheet.map(|sheet| sheet as Rc<dyn oryn_js::v8_bindings::BindingNativeStylesheet>)
            })
    }
fn insert_rule(
    &self,
    index: usize,
    source: &str,
) -> Result<(), oryn_js::v8_bindings::BindingNativeRuleError> {
    use oryn_js::v8_bindings::BindingNativeRuleError as Error;
    if !self.origin_clean() {
        return Err(Error::Security);
    }
    let expected = self.publication.mutation_revision.get();
    let next = expected
        .checked_add(1)
        .ok_or_else(|| Error::Native("stylesheet revision exhausted".into()))?;
    let (count, pending_count) = {
        let graph = self
            .publication
            .graph
            .try_borrow()
            .map_err(|_| Error::Native("insertion context count borrow".into()))?;
        let pending = self
            .publication
            .pending_imports
            .try_borrow()
            .map_err(|_| Error::Native("insertion queue count borrow".into()))?;
        (graph.completion_context_count(), pending.len())
    };
    let pending_capacity = pending_count
        .checked_add(1)
        .ok_or_else(|| Error::Native("insertion pending count overflow".into()))?;
    let bytes = count
        .checked_mul(std::mem::size_of::<
            oryn_layout::cssom::native_import_graph::NativeImport,
        >())
        .and_then(|n| {
            n.checked_add(pending_capacity.checked_mul(std::mem::size_of::<
                oryn_layout::cssom::native_import_graph::OccurrenceId,
            >())?)
        })
        .ok_or_else(|| Error::Native("insertion context overflow".into()))?;
    let charge = self
        .publication
        .admission
        .reserve(bytes)
        .map_err(Error::Native)?;
    let mut entries = Vec::new();
    entries
        .try_reserve_exact(count)
        .map_err(|e| Error::Native(e.to_string()))?;
    let mut pending = Vec::new();
    pending
        .try_reserve_exact(pending_capacity)
        .map_err(|e| Error::Native(e.to_string()))?;
    let context = self
        .publication
        .graph
        .try_borrow()
        .map_err(|_| Error::Native("insertion context capture borrow".into()))?
        .completion_context(entries)
        .map_err(Error::Native)?;
    let mut prepared = context
        .prepare_rule_insertion(
            &self.sheet,
            index,
            source,
            self.publication.admission.as_ref(),
        )
        .map_err(binding_native_rule_error)?;
    let allocation_count = self
        .publication
        .responses
        .try_borrow()
        .map_err(|_| Error::Native("insertion charge count borrow".into()))?
        .allocations
        .len();
    let allocation_capacity = allocation_count
        .checked_add(1)
        .ok_or_else(|| Error::Native("insertion charge overflow".into()))?;
    let allocation_bytes = allocation_capacity
        .checked_mul(std::mem::size_of::<std::sync::Arc<dyn Send + Sync>>())
        .ok_or_else(|| Error::Native("insertion charge bytes overflow".into()))?;
    let allocation_lease = self
        .publication
        .admission
        .reserve(allocation_bytes)
        .map_err(Error::Native)?;
    let charge: std::sync::Arc<dyn Send + Sync> = std::sync::Arc::new((charge, allocation_lease));
    let mut allocations = Vec::new();
    allocations
        .try_reserve_exact(allocation_capacity)
        .map_err(|e| Error::Native(e.to_string()))?;
    self.publication
        .admission
        .checkpoint()
        .map_err(Error::Native)?;
    if self
        .publication
        .cssom_execution_retired()
        .map_err(|e| Error::Native(e.to_string()))?
    {
        return Err(Error::Native("stylesheet insertion owner retired".into()));
    }
    let mut store = self
        .publication
        .responses
        .try_borrow_mut()
        .map_err(|_| Error::Native("insertion charge commit borrow".into()))?;
    let mut queue = self
        .publication
        .pending_imports
        .try_borrow_mut()
        .map_err(|_| Error::Native("insertion queue commit borrow".into()))?;
    let mut graph = self
        .publication
        .graph
        .try_borrow_mut()
        .map_err(|_| Error::Native("insertion graph commit borrow".into()))?;
    if self.publication.mutation_revision.get() != expected
        || queue.len() != pending_count
        || store.allocations.len() != allocation_count
    {
        return Err(Error::Native("insertion snapshot changed".into()));
    }
    let id = graph
        .commit_rule_insertion(&mut prepared)
        .map_err(binding_native_rule_error)?;
    pending.append(&mut queue);
    if let Some(id) = id {
        pending.push(id);
    }
    std::mem::swap(&mut *queue, &mut pending);
    self.publication.mutation_revision.set(next);
    allocations.append(&mut store.allocations);
    allocations.push(charge);
    std::mem::swap(&mut store.allocations, &mut allocations);
    drop(graph);
    drop(queue);
    drop(store);
    Ok(())
}

    fn delete_rule(
        &self,
        index: usize,
    ) -> Result<(), oryn_js::v8_bindings::BindingNativeRuleError> {
        use oryn_js::v8_bindings::BindingNativeRuleError as Error;
        if !self.origin_clean() {
            return Err(Error::Security);
        }
        let revision = self
            .publication
            .mutation_revision
            .get()
            .checked_add(1)
            .ok_or_else(|| Error::Native("stylesheet mutation revision exhausted".into()))?;
        self.publication
            .graph
            .try_borrow_mut()
            .map_err(|_| Error::Native("native sheet mutation borrow conflict".into()))?
            .delete_rule(&self.sheet, index)
            .map_err(binding_native_rule_error)?;
        self.publication.mutation_revision.set(revision);
        Ok(())
    }
}
impl NativeRuleHandle {
    fn origin_clean(&self) -> bool {
        let owner = self.rule.owner();
        let Ok(responses) = self.publication.responses.try_borrow() else { return false; };
        responses.entries.iter()
            .find(|response| {
                response
                    .sheet
                    .as_ref()
                    .is_some_and(|sheet| sheet.same_sheet(&owner))
            })
            .is_some_and(|response| response.proof.origin_clean())
    }
    fn require_origin_clean(&self) -> Result<(), oryn_js::v8_bindings::BindingNativeCssError> {
        if self.origin_clean() {
            Ok(())
        } else {
            Err(oryn_js::v8_bindings::BindingNativeCssError::Security)
        }
    }
}
